import React from "react";

const doctors = [
  {
    name: "Dr. Calvin Carlo",
    specialty: "Eye Care",
    experience: "3 Years Experienced",
    image: "https://example.com/dr-calvin.jpg", // Replace with actual image URL
  },
  {
    name: "Dr. Cristino Murphy",
    specialty: "Gynecology",
    experience: "5 Years Experienced",
    image: "https://example.com/dr-cristino.jpg", // Replace with actual image URL
  },
  {
    name: "Dr. Alia Reddy",
    specialty: "Psychotherapy",
    experience: "4 Years Experienced",
    image: "https://example.com/dr-alia.jpg", // Replace with actual image URL
  },
  {
    name: "Dr. Toni Kovar",
    specialty: "Orthopedic",
    experience: "6 Years Experienced",
    image: "https://example.com/dr-toni.jpg", // Replace with actual image URL
  },
];

const DoctorCard = ({ name, specialty, experience, image }) => {
  return (
    <div className="flex items-center space-x-4 p-4 bg-white rounded-lg shadow-md mb-4">
      <img
        src={image}
        alt={name}
        className="w-16 h-16 rounded-md object-cover"
      />
      <div>
        <h3 className="text-lg font-semibold text-gray-800">{name}</h3>
        <p className="text-sm text-gray-500">{specialty}</p>
        <p className="text-sm text-gray-400">{experience}</p>
      </div>
    </div>
  );
};

const DoctorsList = () => {
  return (
    <div className="max-w-lg mx-auto bg-gray-50 p-6 rounded-lg shadow-lg">
      <h2 className="text-2xl font-bold mb-6 text-gray-800">Doctors List</h2>
      <div className="space-y-4">
        {doctors.map((doctor, index) => (
          <DoctorCard
            key={index}
            name={doctor.name}
            specialty={doctor.specialty}
            experience={doctor.experience}
            image={doctor.image}
          />
        ))}
      </div>
    </div>
  );
};

export default DoctorsList;
